/**
 * Raises every CocoaPods target (and its resource-bundle targets) to the
 * app's minimum iOS version. Some pods (RNCAsyncStorage, RNSVG,
 * SDWebImage) still declare iOS 9-13.4, which current Xcode rejects.
 *
 * `ios/` is generated by `expo prebuild` and git-ignored, so a hand edit to
 * the Podfile is lost on the next prebuild / EAS build. This plugin
 * re-applies the fix every time.
 */
const fs = require('fs');
const path = require('path');
const { withDangerousMod } = require('@expo/config-plugins');

const MARKER = '# @generated withPodsDeploymentTarget';

module.exports = function withPodsDeploymentTarget(config, { minimum = '15.1' } = {}) {
  return withDangerousMod(config, [
    'ios',
    async (cfg) => {
      const podfilePath = path.join(cfg.modRequest.platformProjectRoot, 'Podfile');
      let podfile = fs.readFileSync(podfilePath, 'utf8');
      if (podfile.includes(MARKER)) return cfg;

      const snippet = `
    ${MARKER}
    installer.pods_project.targets.each do |target|
      target.build_configurations.each do |build_config|
        current = build_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET']
        if current.nil? || Gem::Version.new(current) < Gem::Version.new('${minimum}')
          build_config.build_settings['IPHONEOS_DEPLOYMENT_TARGET'] = '${minimum}'
        end
      end
    end
`;
      const anchor = /(post_install do \|installer\|\n)/;
      if (!anchor.test(podfile)) {
        throw new Error('withPodsDeploymentTarget: could not find post_install in the Podfile');
      }
      podfile = podfile.replace(anchor, `$1${snippet}`);
      fs.writeFileSync(podfilePath, podfile);
      return cfg;
    },
  ]);
};
